{
  "dependencies": {
    "@myko/core": "^4.24.2",
    "@opencode-ai/plugin": "^1.17.11"
  },
  "description": "opencode plugin that connects an opencode session to the marshal coordination daemon — roster registration, send_message/broadcast/join_room/leave_room/set_status tools, and real-time + per-turn delivery of sibling-agent messages. The opencode-native counterpart of the Claude Code marshal-shim, built on opencode's plugin hooks instead of a shim binary.",
  "devDependencies": {
    "@types/bun": "^1.3.14",
    "typescript": "^5.3.3"
  },
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "README.md"
  ],
  "flux": {
    "tasks": [
      "check",
      "publish"
    ]
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "marshal",
    "agent-coordination"
  ],
  "license": "MIT OR Apache-2.0",
  "main": "./src/index.ts",
  "name": "@agent-marshal/marshal-opencode",
  "repository": {
    "directory": "plugins/marshal-opencode",
    "type": "git",
    "url": "https://github.com/ignition-is-go/marshal"
  },
  "scripts": {
    "check": "tsc --noEmit"
  },
  "type": "module",
  "version": "0.52.0"
}
